{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-qzSvY2/src/lcs.js","content":"/**
 * Longest-common-subsequence diffing of one side's lines against the base's
 * lines, with the tie-break rule the task specifies: among equally long
 * subsequences, prefer the one whose matches come earliest, advancing base
 * over the other side when a step is ambiguous.
 */

/**
 * Diff `side` against `base` and return the list of changes: runs of base
 * lines replaced by runs of side lines. An insertion has an empty base run;
 * a deletion has an empty side run.
 *
 * @param {string[]} side
 * @param {string[]} base
 * @returns {{baseStart: number, baseEnd: number, ownStart: number, ownEnd: number}[]}
 */
export function diffAgainstBase(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] holds the LCS length of side[i:] and base[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = dp[i]
    const nextRow = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      row[j] = side[i] === base[j] ? nextRow[j + 1] + 1 : Math.max(nextRow[j], row[j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let gapBaseStart = 0
  let gapSideStart = 0

  while (i < n && j < m) {
    if (side[i] === base[j]) {
      if (gapBaseStart < j || gapSideStart < i) {
        changes.push({ baseStart: gapBaseStart, baseEnd: j, ownStart: gapSideStart, ownEnd: i })
      }
      i++
      j++
      gapBaseStart = j
      gapSideStart = i
    } else if (dp[i + 1][j] > dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  if (gapBaseStart < m || gapSideStart < n) {
    changes.push({ baseStart: gapBaseStart, baseEnd: m, ownStart: gapSideStart, ownEnd: n })
  }

  return changes
}
"}

