{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-qzSvY2/src/merge3.js","content":"/**
 * Three-way merge of `mine` and `theirs` against their common `base`,
 * implementing the region-grouping and resolution rules the task specifies.
 */

import { diffAgainstBase } from './lcs.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Group the changes from both sides into regions, in the order they appear
 * in the base: a region starts at the first ungrouped change and keeps
 * absorbing further changes that start at or before its current end.
 */
function buildRegions(mineChanges, theirChanges) {
  const all = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirChanges.map(c => ({ ...c, side: 'theirs' })),
  ]
  all.sort((a, b) => a.baseStart - b.baseStart || (a.side === 'mine' ? -1 : 1))

  const regions = []
  let current = null
  for (const change of all) {
    if (current && change.baseStart <= current.baseEnd) {
      current.baseEnd = Math.max(current.baseEnd, change.baseEnd)
      current.changes.push(change)
    } else {
      current = { baseStart: change.baseStart, baseEnd: change.baseEnd, changes: [change] }
      regions.push(current)
    }
  }
  return regions
}

/**
 * Compute one side's replacement lines for a region: if that side made no
 * change within the region its lines are just the base's, otherwise the
 * replacement spans from the earliest of its own changes to the latest,
 * extended by however far the region reaches beyond them.
 */
function sideLinesForRegion(sideChanges, region, ownLines, baseLines) {
  if (sideChanges.length === 0) return baseLines.slice(region.baseStart, region.baseEnd)
  const first = sideChanges[0]
  const last = sideChanges[sideChanges.length - 1]
  const startOffset = first.baseStart - region.baseStart
  const endOffset = region.baseEnd - last.baseEnd
  return ownLines.slice(first.ownStart - startOffset, last.ownEnd + endOffset)
}

/**
 * Split the base document into an ordered list of blocks: stable runs kept
 * unchanged, and regions resolved per the task's rules (clean or conflict).
 *
 * @returns {Array<
 *   | { kind: 'stable', lines: string[] }
 *   | { kind: 'mine' | 'theirs' | 'both', lines: string[] }
 *   | { kind: 'conflict', mine: string[], base: string[], theirs: string[] }
 * >}
 */
export function computeBlocks(mineLines, baseLines, theirLines) {
  const mineChanges = diffAgainstBase(mineLines, baseLines)
  const theirChanges = diffAgainstBase(theirLines, baseLines)
  const regions = buildRegions(mineChanges, theirChanges)

  const blocks = []
  let lastEnd = 0
  for (const region of regions) {
    if (region.baseStart > lastEnd) {
      blocks.push({ kind: 'stable', lines: baseLines.slice(lastEnd, region.baseStart) })
    }

    const mineInRegion = region.changes.filter(c => c.side === 'mine')
    const theirsInRegion = region.changes.filter(c => c.side === 'theirs')
    const mine = sideLinesForRegion(mineInRegion, region, mineLines, baseLines)
    const theirs = sideLinesForRegion(theirsInRegion, region, theirLines, baseLines)
    const base = baseLines.slice(region.baseStart, region.baseEnd)

    if (linesEqual(mine, theirs)) {
      blocks.push({ kind: 'both', lines: mine })
    } else if (linesEqual(mine, base)) {
      blocks.push({ kind: 'theirs', lines: theirs })
    } else if (linesEqual(theirs, base)) {
      blocks.push({ kind: 'mine', lines: mine })
    } else {
      blocks.push({ kind: 'conflict', mine, base, theirs })
    }

    lastEnd = region.baseEnd
  }

  if (lastEnd < baseLines.length) {
    blocks.push({ kind: 'stable', lines: baseLines.slice(lastEnd, baseLines.length) })
  }

  return blocks
}
"}

