 * Parse the CLI's standard-input format: three documents separated by lines
 * that are exactly `%%%`.
 */

const SEPARATOR = '%%%'

/**
 * @param {string} raw the full contents of standard input
 * @returns {string[][]} the three documents, each a list of lines
 * @throws {Error} when the input does not hold exactly three documents
 */
export function parseInput(raw) {
  const lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }
  return parts
}
"}

