{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-qzSvY2/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { computeBlocks } from './merge3.js'
import { parseInput } from './parseInput.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderMerge(blocks, includeBase) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine', ...block.mine)
      if (includeBase) out.push('||||||| base', ...block.base)
      out.push('=======', ...block.theirs, '>>>>>>> theirs')
    } else {
      out.push(...block.lines)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}

function renderRegions(blocks) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${block.mine.length} base=${block.base.length} theirs=${block.theirs.length}`)
    } else {
      out.push(`${block.kind} ${block.lines.length}`)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseInput(readStdin())
  } catch (err) {
    fail(err.message)
    return
  }

  const blocks = computeBlocks(mine, base, theirs)
  const { text, conflict } =
    mode === 'regions' ? renderRegions(blocks) : renderMerge(blocks, mode === 'merge')

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

